BEGIN;
SET LOCAL ROLE celebix_saas_owner;
DO $assert$DECLARE fnrecord record;BEGIN
 IF(SELECT count(*)FROM saas.store_tool_legacy265_functions)<>6 OR(SELECT count(*)FROM saas.store_tool_legacy265_functions WHERE is_new)<>2 THEN RAISE EXCEPTION 'STORE_TOOL265_MANIFEST_INVALID';END IF;
 FOR fnrecord IN SELECT *FROM saas.store_tool_legacy265_functions LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=fnrecord.function_oid AND p.oid=to_regprocedure(fnrecord.signature)AND p.proowner=fnrecord.function_owner AND p.proacl IS NOT DISTINCT FROM fnrecord.function_acl AND p.proconfig IS NOT DISTINCT FROM fnrecord.function_config AND p.prosecdef=fnrecord.function_security AND p.provolatile=fnrecord.function_volatility AND p.proisstrict=fnrecord.function_strict AND p.proparallel=fnrecord.function_parallel AND p.prolang=fnrecord.function_language AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')=fnrecord.published_sha256)OR encode(sha256(convert_to(fnrecord.definition,'UTF8')),'hex')<>fnrecord.original_sha256 THEN RAISE EXCEPTION 'STORE_TOOL265_SOURCE_DRIFT:%',fnrecord.signature;END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM pg_class c WHERE c.oid=ANY(ARRAY['saas.store_tool_legacy_releases'::regclass,'saas.store_tool_legacy265_functions'::regclass])AND(NOT c.relrowsecurity OR NOT c.relforcerowsecurity OR c.relowner<>'celebix_saas_owner'::regrole))THEN RAISE EXCEPTION 'STORE_TOOL265_RLS_INVALID';END IF;
 IF EXISTS(SELECT 1 FROM pg_roles r WHERE r.rolname LIKE 'celebix_saas_%'AND r.rolname<>'celebix_saas_owner'AND(has_table_privilege(r.oid,'saas.store_tool_legacy_releases','SELECT,INSERT,UPDATE,DELETE')OR has_table_privilege(r.oid,'saas.store_tool_legacy265_functions','SELECT,INSERT,UPDATE,DELETE')OR has_function_privilege(r.oid,'saas.store_tool_effective_licenses(uuid,timestamptz)','EXECUTE')OR has_function_privilege(r.oid,'saas.store_tool_legacy_release_guard()','EXECUTE')))THEN RAISE EXCEPTION 'STORE_TOOL265_PRIVATE_AUTHORITY_EXPOSED';END IF;
 IF EXISTS(SELECT 1 FROM aclexplode((SELECT proacl FROM pg_proc WHERE oid='saas.store_tool_effective_licenses(uuid,timestamptz)'::regprocedure))WHERE grantee=0 AND privilege_type='EXECUTE')THEN RAISE EXCEPTION 'STORE_TOOL265_PUBLIC_AUTHORITY_EXPOSED';END IF;
 IF EXISTS(SELECT 1 FROM saas.store_tool_legacy_releases w LEFT JOIN saas.store_tool_licenses l USING(store_id,tool_key)WHERE l.source IS DISTINCT FROM 'grandfathered'OR w.released_at<l.granted_at OR w.executed_by IS NULL OR w.executed_role IS NULL)THEN RAISE EXCEPTION 'STORE_TOOL265_LEGACY_HISTORY_INVALID';END IF;
 IF EXISTS(SELECT p.store_id,k FROM saas.store_tool_purchases p CROSS JOIN unnest(p.tool_keys)k WHERE p.status='settled'GROUP BY p.store_id,k HAVING count(*)>1)THEN RAISE EXCEPTION 'STORE_TOOL265_DUPLICATE_PAID_OWNERSHIP';END IF;
 IF EXISTS(SELECT 1 FROM saas.store_tool_legacy_releases w JOIN saas.store_tool_purchases p ON p.store_id=w.store_id AND w.tool_key=ANY(p.tool_keys)AND p.status='settled'LEFT JOIN saas.store_tool_receipts r ON r.store_id=p.store_id AND r.purchase_id=p.id WHERE p.settled_at<w.released_at OR r.amount_cents IS DISTINCT FROM p.total_cents)THEN RAISE EXCEPTION 'STORE_TOOL265_REGRANT_PAYMENT_INVALID';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='saas.store_tool_licenses'::regclass AND tgname='store_tool_licenses_immutable'AND tgfoid='saas.platform_append_only()'::regprocedure AND tgenabled='O')OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='saas.store_tool_legacy_releases'::regclass AND tgname='store_tool_legacy_release_immutable'AND tgfoid='saas.platform_append_only()'::regprocedure AND tgenabled='O')THEN RAISE EXCEPTION 'STORE_TOOL265_HISTORY_NOT_IMMUTABLE';END IF;
END $assert$;
COMMIT;
